import { useCallback } from 'react';

export default function useOptionController({ cartes, setCartes, setOptionAlerte, t }) {
    const handleOptionSelect = useCallback((option, index, selectedValue) => {
        const updatedCartes = [...cartes];
        const selectedOption = { ...option, selectedValue: selectedValue };
        let alertMessage = null;

        // Contrôle 1: Vérifier au moins une option principale de formation
        const hasPrincipalOption = updatedCartes[index].options.some(opt => opt.principale !== undefined && opt.principale);
        if ((hasPrincipalOption === false) && (option.principale === undefined || !option.principale)) {
            alertMessage = t('alert.select_main_formation_option');
            setOptionAlerte(<span>{alertMessage}</span>);
            return;
        }

        // Contrôle 2: Vérifier l'unicité
        const hasSimilarOption = updatedCartes[index].options.some(opt => opt.unique === option.unique);
        if ((option.unique || option.unique !== undefined) && hasSimilarOption) {
            alertMessage = t('alert.similar_option_selected');
            setOptionAlerte(<span>{alertMessage}</span>);
            return;
        }

        // Contrôle 3: Vérifier la limite d'option (kustomlimit support)
        const selectedOptionCount = updatedCartes[index].options.filter(opt => opt.name === option.name).length;
        let limit;
        if (option.kustomlimitoption) {
            const selectedKustomlimitOption = updatedCartes[index].options.find(opt => opt.kustomlimit);
            if (selectedKustomlimitOption) {
                const kustomlimitValue = selectedKustomlimitOption.kustomlimit;
                limit = option.limit * kustomlimitValue;
            } else {
                limit = option.limit || 1;
            }
        } else {
            limit = option.limit || 0;
        }
        if (limit > 0 && selectedOptionCount >= limit) {
            alertMessage = t('alert.cannot_add_more');
            setOptionAlerte(<span>{alertMessage}</span>);
            return;
        }

        // Contrôle 4: limiteOptionGlobal
        if (option.limiteOptionGlobal) {
            const limitOptionGlobal = option.limiteOptionGlobal;
            const globalOptionCount = updatedCartes.reduce((total, carte) => total + carte.options.filter(opt => opt.name === option.name).length, 0);
            if (limitOptionGlobal > 0 && globalOptionCount >= limitOptionGlobal) {
                alertMessage = t('alert.list_option_limit_reached');
                setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Contrôle 5: limiteOptionFormation (exclut tagrefoptions, refoption et IsNotOption)
        if (!option.principale && updatedCartes[index].limiteOptionFormation) {
            const limiteOptionFormation = updatedCartes[index].limiteOptionFormation || 0;
            const optionsSansPrincipaleCount = updatedCartes[index].options.filter(
                opt => !opt.principale && !opt.tagrefoptions && !opt.refoption && !opt.IsNotOption
            ).length;
            if ((optionsSansPrincipaleCount >= limiteOptionFormation)) {
                alertMessage = t('alert.option_limit_reached');
                setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Controle si les options sont ajoutées à la bonne carte (optionbase)
        if (!updatedCartes[index].optionbase.some(optionBase => optionBase.name === selectedOption.name)) {
            alertMessage = t('alert.option_not_allowed');
            setOptionAlerte(<span>{alertMessage}</span>);
            return;
        }

        // Refoption : vérifier nbrefoptions
        if (selectedOption.refoption) {
            const optionsAvecRef = updatedCartes[index].options.filter(opt => opt.refoption === true);
            const sommeValeurOptionsAvecRef = optionsAvecRef.reduce((somme, opt) => somme + (opt.selectedValue || 0), 0);
            const sommeTotaleAvecNouvelleOption = sommeValeurOptionsAvecRef + (selectedOption.selectedValue || 0);

            const nbrefoptions = updatedCartes[index].options.reduce((acc, opt) => {
                return opt.nbrefoptions ? acc + opt.nbrefoptions : acc;
            }, 0);

            if (sommeTotaleAvecNouvelleOption > nbrefoptions && nbrefoptions != 0) {
                alertMessage = t('alert.option_limit_exceeded', {
                    selected: sommeTotaleAvecNouvelleOption,
                    limit: nbrefoptions
                });
                setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Contrôle 7 (doublon dans l'original) : vérification option autorisée pour la formation
        if (!updatedCartes[index].optionbase.some(opt => opt.name === selectedOption.name)) {
            alertMessage = t('alert.option_not_allowed');
            setOptionAlerte(<span>{alertMessage}</span>);
            return;
        }

        //COntrole 8 : 1 Commissaire par tranche de 1000 pts
        if (selectedOption.commissaire) {
            const totalPoints = cartes.reduce((total, carte) => {
                const cartePoints = carte.options.reduce((carteTotal, opt) => {
                    return carteTotal + (opt.value * (opt.selectedValue || 0));
                }, 0);
                return total + cartePoints;
            }, 0);
            const maxCommissairesAllowed = Math.ceil(totalPoints / 1000);
            const currentCommissairesCount = cartes.reduce((count, carte) => {
                return count + carte.options.filter(opt => opt.commissaire).length;
            }, 0);
            if (currentCommissairesCount >= maxCommissairesAllowed) {
                alertMessage = t('Il faut plus de points pour ajouter un commissaire', {
                    limit: maxCommissairesAllowed
                });
                setOptionAlerte(<span>{alertMessage}</span>);
                return;
            }
        }

        // Ajout de l'option
        updatedCartes[index].options.push(selectedOption);
        setCartes(updatedCartes);
        setOptionAlerte(null);
    }, [cartes, setCartes, setOptionAlerte, t]);

    return { handleOptionSelect };
}