import React from "react";
import MainProvider from './Contexts/MainContext';
import MainPage from './Pages/MainPage';
import MainPageB from './Pages/MainPageB';
import PrintPage from './Pages/PrintPage';
import Header from './Components/Header';
import Footer from './Components/Footer';
import PrintCaracs from "./Pages/PrintCaracs";
import { ThemeProvider } from '@mui/material/styles';
import { useMediaQuery } from "@mui/material";
import Theme from './Components/theme';
import ReactGA from "react-ga4";
import GamePage from "./Pages/GamePage";
import NotePage from "./Pages/VersionPage";
import RulePage from "./Pages/RulePage";
import './i18n';

function App() {
  ReactGA.initialize("G-GN7PQ8D552");

  // Define the media query condition
  const isSmallScreen = useMediaQuery('(max-width:800px)');
  return (
    <ThemeProvider theme={Theme}>
      <MainProvider>
        <Header ></Header>
        {isSmallScreen ? <MainPage /> : <MainPageB />}
        <PrintPage></PrintPage>
        <PrintCaracs></PrintCaracs>
        <NotePage></NotePage>
        <RulePage></RulePage>
        <GamePage></GamePage>
        <Footer></Footer>
      </MainProvider>
    </ThemeProvider>
  );
}

export default App;